function hexPoints(cx, cy, r, rot) {
  var pts = [];
  for (var i = 0; i < 6; i++) {
    var a = (rot + 60 * i) * Math.PI / 180;
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return pts;
}

function lineIn(g, p1, p2, offx, offy) {
  g.line(p1[0] + offx, p1[1] + offy, p2[0] + offx, p2[1] + offy)
    .stroke({ color: BLACK, width: 1.7 });
}

function drawRing(g, cx, cy, r, rot, doubleIdxs) {
  var pts = hexPoints(cx, cy, r, rot);
  g.polygon(pts.map(function(p) { return p.join(','); }).join(' '))
    .fill('none').stroke({ color: BLACK, width: 1.8 });
  var c = [cx, cy];
  doubleIdxs.forEach(function(idx) {
    var p1 = pts[idx], p2 = pts[(idx + 1) % 6];
    var mx = (p1[0] + p2[0]) / 2, my = (p1[1] + p2[1]) / 2;
    var vx = c[0] - mx, vy = c[1] - my;
    var len = Math.sqrt(vx * vx + vy * vy) || 1;
    lineIn(g, p1, p2, vx / len * 9, vy / len * 9);
  });
  return pts;
}

function drawBenzene(cx, cy, scale) {
  var g = draw.group();
  drawRing(g, cx, cy, 45 * scale, -30, [0, 2, 4]);
  return g;
}

function drawBromobenzene(cx, cy, scale) {
  var g = draw.group();
  var pts = drawRing(g, cx, cy, 45 * scale, -30, [0, 2, 4]);
  var p = pts[0], q = [p[0] + 38 * scale, p[1] - 22 * scale];
  g.line(p[0], p[1], q[0], q[1]).stroke({ color: BLACK, width: 1.7 });
  g.text('Br').font({ family: 'Arial', size: 22 * scale, anchor: 'start' })
    .fill(MAG).move(q[0] + 2, q[1] - 16 * scale);
  return g;
}

function drawIntermediate(cx, cy, scale) {
  var g = draw.group();
  var pts = drawRing(g, cx, cy, 47 * scale, -30, [2, 4]);
  var p = pts[0];
  var hEnd = [p[0] + 33 * scale, p[1] - 20 * scale];
  var brEnd = [p[0] + 30 * scale, p[1] + 23 * scale];
  g.line(p[0], p[1], hEnd[0], hEnd[1]).stroke({ color: BLACK, width: 1.7 });
  g.line(p[0], p[1], brEnd[0], brEnd[1]).stroke({ color: BLACK, width: 1.7 });
  g.text('H').font({ family: 'Arial', size: 20 * scale, anchor: 'start' })
    .fill(BLACK).move(hEnd[0] + 2, hEnd[1] - 17 * scale);
  g.text('Br').font({ family: 'Arial', size: 22 * scale, anchor: 'start' })
    .fill(MAG).move(brEnd[0] + 2, brEnd[1] - 8 * scale);
  g.text('+').font({ family: 'Arial', size: 21 * scale, anchor: 'middle' })
    .fill(BLACK).center(cx, cy - 57 * scale);
  return g;
}

function drawAdditionProduct(cx, cy, scale) {
  var g = draw.group();
  var pts = drawRing(g, cx, cy, 47 * scale, -30, [2, 4]);
  var top = pts[5], upperRight = pts[0];

  g.line(top[0], top[1], top[0] - 18 * scale, top[1] - 33 * scale)
    .stroke({ color: BLACK, width: 1.55 });
  g.text('H').font({ family: 'Arial', size: 20 * scale, anchor: 'end' })
    .fill(BLACK).move(top[0] - 32 * scale, top[1] - 52 * scale);

  g.line(top[0], top[1], top[0] + 17 * scale, top[1] - 34 * scale)
    .stroke({ color: BLACK, width: 1.55 });
  g.text('Br').font({ family: 'Arial', size: 20 * scale, anchor: 'start' })
    .fill(MAG).move(top[0] + 18 * scale, top[1] - 51 * scale);

  g.line(upperRight[0], upperRight[1], upperRight[0] + 31 * scale, upperRight[1] - 16 * scale)
    .stroke({ color: BLACK, width: 1.55 });
  g.text('Br').font({ family: 'Arial', size: 20 * scale, anchor: 'start' })
    .fill(MAG).move(upperRight[0] + 32 * scale, upperRight[1] - 35 * scale);

  g.line(upperRight[0], upperRight[1], upperRight[0] + 29 * scale, upperRight[1] + 19 * scale)
    .stroke({ color: BLACK, width: 1.55 });
  g.text('H').font({ family: 'Arial', size: 20 * scale, anchor: 'start' })
    .fill(BLACK).move(upperRight[0] + 30 * scale, upperRight[1] + 7 * scale);

  g.path('M' + (cx - 62 * scale) + ' ' + (cy - 82 * scale) +
    ' L' + (cx - 73 * scale) + ' ' + (cy - 82 * scale) +
    ' L' + (cx - 73 * scale) + ' ' + (cy + 70 * scale) +
