function pointOn(path, frac) {
  var n = path.node;
  var len = n.getTotalLength();
  var p = n.getPointAtLength(Math.max(0, Math.min(1, frac)) * len);
  return { x: p.x, y: p.y };
}

function pointForStage(stage, pathChoice) {
  if (pathChoice === 'Addition' && (stage === 'second transition state' || stage === 'products')) {
    return pointOn(addPath, stage === 'second transition state' ? 0.55 : 1);
  }
  return pointOn(subPath, stageFractionsSub[stage] == null ? 0 : stageFractionsSub[stage]);
}

