function refreshFigure() {
  activePath = document.getElementById('pathwayChoiceInput').checked ? 'Addition' : 'Substitution';

  if (!interactionStarted) {
    subPath.stroke({ color: BLACK, width: 4.7, opacity: 1 });
    addPath.stroke({ color: MAG, width: 4.2, opacity: 1 });
    prodMol.opacity(1);
    addMol.opacity(1);
    marker.opacity(0);
    setGlow('');
    return;
  }

  subPath.stroke({
    color: BLACK,
    width: activePath === 'Substitution' ? 5.3 : 2.8,
    opacity: activePath === 'Substitution' ? 1 : 0.38
  });
  addPath.stroke({
    color: MAG,
    width: activePath === 'Addition' ? 5.1 : 3.1,
    opacity: activePath === 'Addition' ? 1 : 0.48
  });
  prodMol.opacity(activePath === 'Substitution' ? 1 : 0.45);
  addMol.opacity(activePath === 'Addition' ? 1 : 0.78);

  var p = pointForStage(activeStage, activePath);
  marker.opacity(1).front();
  marker.animate(180).center(p.x, p.y);
  marker.fill(activePath === 'Addition' && (activeStage === 'second transition state' || activeStage === 'products') ? MAG : '#fff200');

  if (activeStage === 'reactants') setGlow('reactants');
  else if (activeStage === 'cationic intermediate') setGlow('intermediate');
  else if (activeStage === 'products') setGlow(activePath === 'Addition' ? 'addition' : 'products');
  else setGlow('');
}

